mapper.select:
SELECT t1.id, t1.goods_name, t1.goods_barcode, t1.specification, t1.model, t1.is_unit, t1.custom_unit, t1.unit_id, t1.goods_images, t1.colour, t1.is_enabled, t1.brand_id, t1.mnemonic_code, t1.goods_status, t1.category_type, t1.manufacturer, t1.serial_number, t1.lot_number, t1.multiattribute, t2.brand_name FROM goods_info t1 LEFT JOIN brand_type t2 ON t1.brand_id = t2.id WHERE t1.is_deleted = 0
AND ( t1.goods_name LIKE CONCAT('%', #{params.query}, '%') OR t1.mnemonic_code LIKE CONCAT('%', #{params.query}, '%') OR t1.specification LIKE CONCAT('%', #{params.query}, '%') OR t1.goods_barcode LIKE CONCAT('%', #{params.query}, '%') )
AND t1.specification = #{params.specification}
AND t1.colour = #{params.colour}
AND t1.brand_id = #{params.brandId}
AND t1.mnemonic_code = #{params.mnemonicCode}
AND t1.goods_status = #{params.goodsStatus}
AND t1.category_type = #{params.categoryType}
AND t1.manufacturer = #{params.manufacturer}
AND t1.is_enabled = #{params.isEnabled}
ORDER BY t1.create_time DESC
